{
  "name": "get_weather",
  "description": "View the current weather in the specified city. Used when the user asks about the weather, temperature, and whether it will rain. It takes a city name and returns weather information as a string.",
  "input_schema": {
    "type": "object",
    "properties": {
      "location": {
        "type": "string",
        "description": "City name. Example: Seoul"
      }
    },
    "required": ["location"]
  },
  "input_examples": [
    {"location": "Seoul"}
  ]
}
